/**
 * Cloudflare Worker entry: the Next.js app (generated by `opennextjs-cloudflare build`)
 * plus a scheduled handler that runs the reminder job from the cron trigger in wrangler.jsonc.
 */
// @ts-ignore: generated at build time
import { default as handler } from "./.open-next/worker.js";

type Env = { APP_URL?: string; CRON_SECRET?: string } & Record<string, unknown>;
type Ctx = { waitUntil(p: Promise<unknown>): void; passThroughOnException(): void };

export default {
  fetch: handler.fetch,

  async scheduled(_controller: unknown, env: Env, ctx: Ctx) {
    const url = new URL("/api/cron/reminders", env.APP_URL || "https://sedosa.internal");
    const req = new Request(url, { headers: env.CRON_SECRET ? { authorization: `Bearer ${env.CRON_SECRET}` } : {} });
    const res: Response = await handler.fetch(req, env, ctx);
    const body = await res.text();
    if (!res.ok) throw new Error(`Reminder job failed (${res.status}): ${body.slice(0, 300)}`);
    console.log(`Reminder job: ${body.slice(0, 300)}`);
  },
};
